#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        TemperatureGradient::new(v, TemperatureGradientUnit::KelvinPerMeter),
        TemperatureGradient::from_kelvins_per_meter(v)
    );
    assert_eq!(
        TemperatureGradient::from_base(v).convert_to(TemperatureGradientUnit::KelvinPerMeter),
        TemperatureGradient::from_base(v).as_kelvins_per_meter()
    );
    assert_eq!(
        TemperatureGradient::new(v, TemperatureGradientUnit::DegreeCelsiusPerMeter),
        TemperatureGradient::from_degrees_celsius_per_meter(v)
    );
    assert_eq!(
        TemperatureGradient::from_base(v)
            .convert_to(TemperatureGradientUnit::DegreeCelsiusPerMeter),
        TemperatureGradient::from_base(v).as_degrees_celsius_per_meter()
    );
    assert_eq!(
        TemperatureGradient::new(v, TemperatureGradientUnit::DegreeFahrenheitPerFoot),
        TemperatureGradient::from_degrees_fahrenheit_per_foot(v)
    );
    assert_eq!(
        TemperatureGradient::from_base(v)
            .convert_to(TemperatureGradientUnit::DegreeFahrenheitPerFoot),
        TemperatureGradient::from_base(v).as_degrees_fahrenheit_per_foot()
    );
    assert_eq!(
        TemperatureGradient::new(v, TemperatureGradientUnit::DegreeCelsiusPerKilometer),
        TemperatureGradient::from_degrees_celsius_per_kilometer(v)
    );
    assert_eq!(
        TemperatureGradient::from_base(v)
            .convert_to(TemperatureGradientUnit::DegreeCelsiusPerKilometer),
        TemperatureGradient::from_base(v).as_degrees_celsius_per_kilometer()
    );
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = TemperatureGradient::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            TemperatureGradient::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in TemperatureGradientUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        TemperatureGradient::from_base(0.0).auto_unit().unit,
        TemperatureGradientUnit::KelvinPerMeter
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "∆°K/m".parse::<TemperatureGradientUnit>(),
        Ok(TemperatureGradientUnit::KelvinPerMeter)
    );
    assert_eq!(
        format!("2.5 {}", "∆°K/m").parse::<TemperatureGradient>(),
        Ok(TemperatureGradient::new(
            2.5,
            TemperatureGradientUnit::KelvinPerMeter
        ))
    );
    assert_eq!(
        "∆°C/m".parse::<TemperatureGradientUnit>(),
        Ok(TemperatureGradientUnit::DegreeCelsiusPerMeter)
    );
    assert_eq!(
        format!("2.5 {}", "∆°C/m").parse::<TemperatureGradient>(),
        Ok(TemperatureGradient::new(
            2.5,
            TemperatureGradientUnit::DegreeCelsiusPerMeter
        ))
    );
    assert_eq!(
        "∆°F/ft".parse::<TemperatureGradientUnit>(),
        Ok(TemperatureGradientUnit::DegreeFahrenheitPerFoot)
    );
    assert_eq!(
        format!("2.5 {}", "∆°F/ft").parse::<TemperatureGradient>(),
        Ok(TemperatureGradient::new(
            2.5,
            TemperatureGradientUnit::DegreeFahrenheitPerFoot
        ))
    );
    assert_eq!(
        "∆°C/km".parse::<TemperatureGradientUnit>(),
        Ok(TemperatureGradientUnit::DegreeCelsiusPerKilometer)
    );
    assert_eq!(
        format!("2.5 {}", "∆°C/km").parse::<TemperatureGradient>(),
        Ok(TemperatureGradient::new(
            2.5,
            TemperatureGradientUnit::DegreeCelsiusPerKilometer
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<TemperatureGradient>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = TemperatureGradient::from_base(6.0);
    let b = TemperatureGradient::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

